<script>
  const superAdminNavItems = Array.from(document.querySelectorAll('[data-path]'));
  const superAdminActivePath = localStorage.getItem('super-admin-active-path') || 'dashboard';
  const activeNavClasses = ['bg-primary-container', 'text-on-primary-container', 'font-semibold', 'rounded-lg', 'shadow-sm'];
  const inactiveNavClasses = ['text-on-surface-variant'];

  function setSuperAdminActiveNav(path) {
    superAdminNavItems.forEach((item) => {
      const isActive = item.dataset.path === path;
      item.classList.remove(...activeNavClasses, ...inactiveNavClasses);
      item.classList.add(...(isActive ? activeNavClasses : inactiveNavClasses));
      if (isActive) {
        item.setAttribute('aria-current', 'page');
      } else {
        item.removeAttribute('aria-current');
      }
    });
  }

  setSuperAdminActiveNav(superAdminActivePath);
  superAdminNavItems.forEach((item) => {
    item.addEventListener('click', (event) => {
      const path = item.dataset.path;
      localStorage.setItem('super-admin-active-path', path);
      setSuperAdminActiveNav(path);
      if (item.getAttribute('href') === '#') {
        event.preventDefault();
      }
    });
  });

  function triggerDiagnostic() {
    const btn = document.getElementById('btn-diagnostic');
    const label = document.getElementById('diagnostic-label');
    const icon = document.getElementById('diagnostic-icon');
    
    label.innerText = 'Scanning Telemetry...';
    icon.classList.add('animate-spin');
    btn.classList.add('opacity-80');

    setTimeout(() => {
      icon.classList.remove('animate-spin');
      icon.innerText = 'done_all';
      label.innerText = 'All Nodes Nominal';
      btn.classList.remove('bg-primary');
      btn.classList.add('bg-tertiary');
      btn.classList.remove('opacity-80');

      setTimeout(() => {
        icon.innerText = 'sensors';
        label.innerText = 'Run Diagnostic Scan';
        btn.classList.remove('bg-tertiary');
        btn.classList.add('bg-primary');
      }, 3500);
    }, 1200);
  }
</script></main></div>

